// backend/schemas/subscription.schema.js
//
// Strict zod schemas for the customer-facing token/subscription routes.

const { z } = require("./common.schema");

// A raw access token is 64 lowercase hex characters generated by the admin service
const rawTokenSchema = z
  .string({ required_error: "Access token is required.", invalid_type_error: "Access token must be a string." })
  .trim()
  .min(16)
  .max(256);

const redeemTokenSchema = z.object({ token: rawTokenSchema }).strict();

const verifyTokenSchema = z.object({ token: rawTokenSchema }).strict();

// Renewal days are clamped to one year so a caller cannot mint decades of access
const renewSubscriptionSchema = z
  .object({ days: z.number().int().min(1).max(365, "Renewal days must be between 1 and 365.") })
  .strict();

module.exports = {
  rawTokenSchema,
  redeemTokenSchema,
  verifyTokenSchema,
  renewSubscriptionSchema,
  MAX_TOKEN_DAYS: 365,
};
